(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,74068,e=>{"use strict";var o=e.i(80873);function s(e,s){return s.map((s,t)=>{let a=(0,o.getLesson)(s.lesson);if(!a)throw Error(`Unknown lesson "${s.lesson}" in ${e}`);return{...s,id:`${e}-${t+1}`,domain:a.domain}})}let t=s("l1",[{lesson:"cloud-computing",prompt:"What is cloud computing?",options:["Delivering computing services such as servers, storage, and networking over the internet","Buying servers and installing them in your own building","A type of weather forecasting software","Software that only runs offline"],answer:0,explanation:"Cloud computing is renting compute, storage, networking, and more over the internet, usually paying for what you use."},{lesson:"cloud-computing",kind:"complete",prompt:"Paying only for the cloud resources you actually use is called the ____ model.",options:["consumption-based","capital expenditure","fixed-license","dedicated-host"],answer:0,explanation:"The consumption-based model bills for usage — no up-front cost, pay for what you use."},{lesson:"cloud-computing",prompt:"Which type of spending is buying physical servers up front?",options:["Capital expenditure (CapEx)","Operational expenditure (OpEx)","Consumption-based","Serverless"],answer:0,explanation:"CapEx is up-front spending on physical infrastructure. Cloud usage is OpEx."},{lesson:"shared-responsibility",prompt:"In every cloud service type, who is responsible for the physical datacenter?",options:["The cloud provider","The customer","The customer's ISP","Shared 50/50"],answer:0,explanation:"Physical hosts, network, and datacenter are always the cloud provider's responsibility."},{lesson:"shared-responsibility",prompt:"In every cloud service type, who is responsible for the data stored in the cloud?",options:["The customer","The cloud provider","No one","The regulator"],answer:0,explanation:"Information and data always stay the customer's responsibility."},{lesson:"cloud-models",prompt:"Which cloud model combines on-premises infrastructure with public cloud resources?",options:["Hybrid cloud","Public cloud","Private cloud","Community SaaS"],answer:0,explanation:"Hybrid = public cloud plus private/on-premises, working together."},{lesson:"cloud-models",prompt:"In which cloud model is the infrastructure used by a single organization only?",options:["Private cloud","Public cloud","Hybrid cloud","Multi-cloud"],answer:0,explanation:"A private cloud is dedicated to one organization, on-premises or hosted."},{lesson:"cloud-models",prompt:"Using more than one public cloud provider (for example Azure and AWS) is called:",options:["Multi-cloud","Private cloud","A region pair","Serverless"],answer:0,explanation:"Multi-cloud means using multiple public cloud providers."},{lesson:"cloud-benefits",prompt:"Which term means a system can automatically add and remove resources to match demand?",options:["Elasticity","Governance","CapEx","Sovereignty"],answer:0,explanation:"Elasticity is automatic scaling in both directions as load changes."},{lesson:"cloud-benefits",kind:"complete",prompt:"Adding more virtual machines to share the load is called ____ scaling.",options:["horizontal","vertical","diagonal","regional"],answer:0,explanation:"Horizontal = scale out / in (more or fewer instances). Vertical = bigger or smaller instance."},{lesson:"cloud-benefits",prompt:"Which benefit describes keeping an app running even when a component fails?",options:["High availability","Cost predictability","Manageability","Elasticity"],answer:0,explanation:"High availability means designing for uptime despite failures."},{lesson:"cloud-service-types",prompt:"Azure Virtual Machines are an example of which cloud service type?",options:["IaaS","PaaS","SaaS","FaaS only"],answer:0,explanation:"VMs are Infrastructure as a Service — you manage the OS and above."},{lesson:"cloud-service-types",prompt:"Microsoft 365 is an example of which cloud service type?",options:["SaaS","PaaS","IaaS","Private cloud"],answer:0,explanation:"Microsoft 365 is finished software delivered over the internet — SaaS."},{lesson:"cloud-service-types",prompt:"Azure App Service is an example of which cloud service type?",options:["PaaS","IaaS","SaaS","On-premises"],answer:0,explanation:"App Service is a managed platform for web apps — PaaS."},{lesson:"regions-and-zones",prompt:"What is an Azure availability zone?",options:["One or more physically separate datacenters within a region, with independent power, cooling, and networking","A pair of regions in different countries","A logical group of subscriptions","A billing account"],answer:0,explanation:"Availability zones are isolated datacenters inside a region for high availability."},{lesson:"regions-and-zones",prompt:"Which is an example of an Azure sovereign region?",options:["Azure Government (US)","West Europe","A resource group","An availability set"],answer:0,explanation:"Sovereign regions are isolated Azure instances such as Azure Government and Azure operated by 21Vianet in China."},{lesson:"regions-and-zones",prompt:"What is an Azure region?",options:["A geographic area containing one or more datacenters connected by a low-latency network","A single server rack","A type of storage account","A role in RBAC"],answer:0,explanation:"A region is a set of datacenters in a geographic area, networked with low latency."},{lesson:"resource-hierarchy",prompt:"What is a resource group?",options:["A logical container for Azure resources that share a lifecycle","A physical datacenter","A billing account","A security role"],answer:0,explanation:"Resource groups logically group resources so you can manage, secure, and delete them together."},{lesson:"resource-hierarchy",prompt:"Which level sits ABOVE subscriptions in the Azure hierarchy?",options:["Management groups","Resource groups","Resources","Availability zones"],answer:0,explanation:"Management groups → subscriptions → resource groups → resources."},{lesson:"compute",prompt:"Which Azure service runs event-driven code without managing servers?",options:["Azure Functions","Azure Virtual Machines","Azure Virtual Desktop","Azure DNS"],answer:0,explanation:"Azure Functions is serverless, event-driven compute."},{lesson:"compute",prompt:"Which service delivers Windows desktops and apps from the cloud to any device?",options:["Azure Virtual Desktop","Azure Functions","Azure Container Instances","Azure Arc"],answer:0,explanation:"Azure Virtual Desktop is desktop and app virtualization in Azure."},{lesson:"compute",prompt:"What does AKS stand for?",options:["Azure Kubernetes Service","Azure Key Storage","Azure Kernel System","Azure Knowledge Search"],answer:0,explanation:"AKS is Azure Kubernetes Service, the managed container orchestrator."},{lesson:"networking",prompt:"Which service gives a private, dedicated connection from on-premises to Azure that does not use the public internet?",options:["Azure ExpressRoute","Azure VPN Gateway","Azure DNS","VNet peering"],answer:0,explanation:"ExpressRoute is a private connection through a connectivity provider."},{lesson:"networking",prompt:"What is a subnet?",options:["A range of IP addresses inside a virtual network","A separate Azure region","A storage tier","A type of VPN"],answer:0,explanation:"Subnets split a VNet's address space into smaller segments."},{lesson:"storage",prompt:"Which storage service is designed for massive amounts of unstructured data such as images and videos?",options:["Azure Blob Storage","Azure Queue Storage","Azure Table Storage","Azure Disk Storage"],answer:0,explanation:"Blob Storage is object storage for unstructured data."},{lesson:"storage",prompt:"Which storage redundancy option keeps three copies in a single datacenter?",options:["LRS","ZRS","GRS","GZRS"],answer:0,explanation:"Locally redundant storage (LRS) keeps three copies in one datacenter."},{lesson:"storage",prompt:"Which physical device can you use to ship large amounts of data to Azure offline?",options:["Azure Data Box","AzCopy","Azure File Sync","Storage Explorer"],answer:0,explanation:"Azure Data Box is a Microsoft-provided appliance for offline bulk data transfer."},{lesson:"identity",prompt:"What is Microsoft Entra ID?",options:["Microsoft's cloud-based identity and access management service","A virtual machine size","A storage redundancy option","A cost management tool"],answer:0,explanation:"Microsoft Entra ID (formerly Azure AD) is the cloud directory for identity and access."},{lesson:"identity",prompt:"What does MFA stand for?",options:["Multifactor authentication","Managed firewall access","Multiple file archive","Microsoft federated account"],answer:0,explanation:"Multifactor authentication requires two or more verification methods."},{lesson:"security",prompt:'Which security model follows the principle "never trust, always verify"?',options:["Zero Trust","Defense-in-depth","Shared responsibility","Hybrid cloud"],answer:0,explanation:"Zero Trust assumes breach and verifies every request explicitly."},{lesson:"security",prompt:"Which Azure service stores secrets, keys, and certificates securely?",options:["Azure Key Vault","Azure Blob Storage","Azure Advisor","Azure Policy"],answer:0,explanation:"Key Vault is the managed safe for secrets, keys, and certificates."},{lesson:"security",prompt:"Which built-in Azure role can view resources but not change them?",options:["Reader","Contributor","Owner","User Access Administrator"],answer:0,explanation:"Reader is read-only."},{lesson:"cost-management",prompt:"Which tool estimates the cost of Azure services before you deploy them?",options:["Azure Pricing Calculator","Microsoft Cost Management","Azure Monitor","Azure Advisor"],answer:0,explanation:"The Pricing Calculator estimates costs of planned resources."},{lesson:"cost-management",prompt:"What is a tag in Azure?",options:["A name/value pair of metadata attached to a resource","A lock that prevents deletion","A security role","A type of virtual network"],answer:0,explanation:"Tags are metadata labels used for organization and cost reporting."},{lesson:"governance",prompt:"Which service enforces rules on how Azure resources are configured, such as allowed regions?",options:["Azure Policy","Azure RBAC","Azure Monitor","Azure DNS"],answer:0,explanation:"Azure Policy enforces organizational standards on resources."},{lesson:"governance",prompt:"Which two resource lock types exist in Azure?",options:["CanNotDelete and ReadOnly","Allow and Deny","Hot and Cool","Public and Private"],answer:0,explanation:"Locks are CanNotDelete (Delete in the portal) and ReadOnly."},{lesson:"manage-and-deploy",prompt:"Which browser-based shell lets you run Azure CLI or Azure PowerShell without installing anything?",options:["Azure Cloud Shell","Azure Arc","Azure Advisor","Azure DNS"],answer:0,explanation:"Cloud Shell runs in the browser with Bash or PowerShell and the Azure tools preinstalled."},{lesson:"manage-and-deploy",prompt:"Which service extends Azure management to servers and Kubernetes clusters outside Azure?",options:["Azure Arc","Azure Cloud Shell","Azure Virtual Desktop","Azure Files"],answer:0,explanation:"Azure Arc brings on-premises and multicloud resources under Azure management."},{lesson:"monitoring",prompt:"Which service gives personalized recommendations to improve cost, security, reliability, performance, and operational excellence?",options:["Azure Advisor","Azure Service Health","Azure Policy","Azure Arc"],answer:0,explanation:"Azure Advisor analyzes your resources and recommends improvements in five categories."},{lesson:"monitoring",prompt:"Which feature of Azure Monitor watches the performance of a live web application?",options:["Application Insights","Resource locks","Azure DNS","Azure Data Box"],answer:0,explanation:"Application Insights is application performance monitoring (APM)."}]),a=s("l2",[{lesson:"cloud-computing",prompt:"What is the main difference between reserved capacity and Spot pricing?",options:["Reserved is a 1- or 3-year commitment for a discount; Spot uses spare capacity that can be evicted","Reserved can be evicted; Spot is a 3-year commitment","Both are always more expensive than pay-as-you-go","Spot is only for storage; reserved is only for networking"],answer:0,explanation:"Reserved = commit and save, stable. Spot = cheapest, but interruptible."},{lesson:"cloud-computing",prompt:"Which statement compares CapEx and OpEx correctly?",options:["CapEx is spent up front on assets; OpEx is spent over time on services as you use them","CapEx is billed monthly by Azure; OpEx is buying a datacenter","OpEx can never be reduced","CapEx is always cheaper than OpEx"],answer:0,explanation:"Cloud moves most IT spending from CapEx to OpEx."},{lesson:"shared-responsibility",prompt:"Compared with IaaS, what does a customer stop managing when moving to PaaS?",options:["The operating system and runtime","The data","User accounts","Access policies for their app"],answer:0,explanation:"PaaS hands the OS and runtime to the provider; data and identities stay with the customer."},{lesson:"shared-responsibility",prompt:"Which responsibility is shared differently depending on the service type (not always the same party)?",options:["Operating system patching","Physical datacenter security","Classifying your own data","Protecting your user accounts"],answer:0,explanation:"OS patching is the customer's in IaaS and the provider's in PaaS/SaaS. The others never move."},{lesson:"cloud-models",prompt:"Why would a company choose a hybrid cloud over a pure public cloud?",options:["Some workloads must stay on-premises for regulatory or latency reasons while others benefit from cloud scale","Hybrid cloud has no costs","Hybrid cloud removes all security responsibility","Public cloud cannot run web apps"],answer:0,explanation:"Hybrid lets each workload live where it fits best."},{lesson:"cloud-models",prompt:"Public cloud vs private cloud: which is generally true?",options:["Public cloud has no CapEx and scales fast; private cloud gives more control but needs hardware investment","Private cloud is always cheaper","Public cloud gives the customer physical access to servers","Private cloud has unlimited instant scale"],answer:0,explanation:"Public trades control for speed and no up-front cost; private trades cost for control."},{lesson:"cloud-benefits",prompt:"What is the difference between scalability and elasticity?",options:["Scalability is the ability to handle more load; elasticity is doing it automatically, up and down, as demand changes","They mean exactly the same thing","Elasticity only applies to storage","Scalability is automatic; elasticity is manual"],answer:0,explanation:"Elasticity = automatic scalability in both directions."},{lesson:"cloud-benefits",prompt:"High availability vs reliability — which is the best distinction?",options:["High availability is about uptime; reliability is about recovering from failures and continuing to function","Reliability is about cost; high availability is about security","They are unrelated to the cloud","High availability only applies to on-premises"],answer:0,explanation:"Both fight downtime: HA by staying up, reliability by recovering."},{lesson:"cloud-benefits",prompt:"Performance predictability vs cost predictability — which example is cost predictability?",options:["Using budgets and the pricing calculator to forecast spend","Using autoscale so response times stay steady","Using a load balancer to spread traffic","Adding a CDN to speed up downloads"],answer:0,explanation:"Forecasting and tracking spend is cost predictability. The others keep performance steady."},{lesson:"cloud-service-types",prompt:"IaaS vs PaaS: which statement is correct?",options:["IaaS gives more control over the OS; PaaS removes OS management so you focus on code","PaaS gives more control over the OS than IaaS","IaaS is a finished application","PaaS requires you to patch the hypervisor"],answer:0,explanation:"More control = more responsibility (IaaS). Less control = less work (PaaS)."},{lesson:"cloud-service-types",prompt:"Which service type is best for an off-the-shelf CRM used through a browser?",options:["SaaS","PaaS","IaaS","A private cloud"],answer:0,explanation:"Finished software you just use = SaaS."},{lesson:"regions-and-zones",prompt:"Availability zones vs region pairs — which protects against a whole region going offline?",options:["Region pairs","Availability zones","Availability sets","Resource groups"],answer:0,explanation:"Zones protect within a region. Pairs give you a second region for disaster recovery."},{lesson:"regions-and-zones",prompt:"Zonal vs zone-redundant services — which is true?",options:["A zonal resource is pinned to one zone you choose; a zone-redundant service replicates across zones automatically","Zonal services replicate across regions","Zone-redundant services only run in one datacenter","They are the same thing"],answer:0,explanation:"Zonal = you pick a zone (for example a VM). Zone-redundant = the platform spreads it (for example ZRS storage)."},{lesson:"resource-hierarchy",prompt:"Subscription vs resource group — which is the billing boundary?",options:["Subscription","Resource group","Resource","Availability zone"],answer:0,explanation:"Subscriptions are billing and access boundaries. Resource groups are logical containers inside them."},{lesson:"resource-hierarchy",prompt:"Management group vs resource group — which statement is correct?",options:["Management groups organize subscriptions; resource groups organize resources","Management groups contain VMs directly","Resource groups contain subscriptions","Both are billing accounts"],answer:0,explanation:"MG → subscriptions; RG → resources."},{lesson:"compute",prompt:"VM vs container: which is a key difference?",options:["A VM includes a full guest OS; a container shares the host OS kernel and packages only the app and its dependencies","Containers always need a full Windows license each","VMs start faster than containers","Containers cannot run in Azure"],answer:0,explanation:"Containers are lighter and start faster because they do not carry a full OS."},{lesson:"compute",prompt:"Availability set vs Virtual Machine Scale Set — which is primarily about automatic scaling?",options:["Virtual Machine Scale Set","Availability set","Both equally","Neither"],answer:0,explanation:"Scale sets add/remove identical VMs automatically. Availability sets spread VMs across fault and update domains."},{lesson:"compute",prompt:"Azure Container Instances vs Azure Kubernetes Service — when is ACI the better fit?",options:["Running a single container or simple job quickly with no orchestration","Running hundreds of microservices with rolling updates","Hosting Windows desktops","Managing on-premises servers"],answer:0,explanation:"ACI = simplest, no cluster. AKS = orchestrate many containers."},{lesson:"networking",prompt:"VPN Gateway vs ExpressRoute — which statement is correct?",options:["VPN Gateway sends encrypted traffic over the public internet; ExpressRoute uses a private connection","ExpressRoute uses the public internet; VPN Gateway does not","Both are only for VNet-to-VNet traffic","VPN Gateway is always faster than ExpressRoute"],answer:0,explanation:"Encrypted over internet = VPN. Private circuit = ExpressRoute."},{lesson:"networking",prompt:"NSG vs Azure Firewall — which is true?",options:["NSGs are basic allow/deny rules on a subnet or NIC; Azure Firewall is a managed, stateful, central firewall service","Azure Firewall is free and NSGs are paid","NSGs protect against DDoS floods","They are the same service with two names"],answer:0,explanation:"NSG = simple filter. Azure Firewall = full managed firewall with central policy and FQDN rules."},{lesson:"networking",prompt:"Public endpoint vs private endpoint — which statement is correct?",options:["A private endpoint gives a PaaS service a private IP in your VNet; a public endpoint is reachable from the internet","Private endpoints are reachable from any internet café","Public endpoints only work with ExpressRoute","Private endpoints replace subnets"],answer:0,explanation:"Private endpoint (Private Link) keeps traffic to the service on your private network."},{lesson:"storage",prompt:"Cool vs Archive tier — which is true?",options:["Cool is online with immediate access; Archive is offline and must be rehydrated, which takes hours","Archive is faster than Cool","Cool is the cheapest tier to store data","Archive is for frequently read data"],answer:0,explanation:"Archive is cheapest to store but slowest and costliest to read."},{lesson:"storage",prompt:"GRS vs RA-GRS — what does RA- add?",options:["Read access to the secondary region at any time","Write access to three regions","Zone redundancy in the primary region","Automatic deletion of old data"],answer:0,explanation:"RA = read access to the secondary copy, even before a failover."},{lesson:"storage",prompt:"AzCopy vs Azure Storage Explorer — which is true?",options:["AzCopy is a command-line tool; Storage Explorer is a graphical app","AzCopy is a graphical app; Storage Explorer is a command-line tool","Both only work with Azure SQL Database","Storage Explorer ships physical disks"],answer:0,explanation:"Both move data; one is CLI (scriptable), the other is GUI."},{lesson:"storage",prompt:"Azure Migrate vs Azure Data Box — which is true?",options:["Azure Migrate assesses and migrates servers, databases, and apps; Data Box moves large data offline on a device","Data Box assesses VMs; Azure Migrate ships disks","Both are command-line copy tools","Azure Migrate is a storage tier"],answer:0,explanation:"Migrate = workloads hub. Data Box = physical bulk data transfer."},{lesson:"identity",prompt:"Microsoft Entra ID vs Microsoft Entra Domain Services — which is true?",options:["Entra ID is the cloud identity service; Domain Services provides managed domain join, Group Policy, LDAP, and Kerberos for legacy apps","Domain Services replaces MFA","Entra ID is only for on-premises servers","They are the same service"],answer:0,explanation:"Domain Services gives classic AD features without running your own domain controllers."},{lesson:"identity",prompt:"SSO vs MFA — which statement is correct?",options:["SSO lets users sign in once to access many apps; MFA requires more than one form of verification","SSO requires three passwords","MFA lets you sign in once for all apps","They are the same"],answer:0,explanation:"SSO = convenience (one sign-in). MFA = security (more proof)."},{lesson:"identity",prompt:"Authentication vs authorization — which Azure feature handles authorization to Azure resources?",options:["Azure RBAC","MFA","Passwordless sign-in","SSO"],answer:0,explanation:"Authentication proves who you are; RBAC authorizes what you can do."},{lesson:"security",prompt:"Owner vs Contributor — what can Owner do that Contributor cannot?",options:["Grant access to others (manage role assignments)","Create virtual machines","Delete storage accounts","Read resources"],answer:0,explanation:"Contributor can manage resources but not assign access. Owner can do both."},{lesson:"security",prompt:"Zero Trust vs defense-in-depth — which is true?",options:["Zero Trust is about verifying every request; defense-in-depth is about multiple layers of protection","Defense-in-depth trusts the internal network","Zero Trust uses a single firewall","They are both Azure products you purchase"],answer:0,explanation:"Both are models/strategies, not products, and they complement each other."},{lesson:"security",prompt:"Encryption at rest vs in transit — which example is encryption at rest?",options:["Azure Storage encrypting data saved on disk","HTTPS between a browser and a web app","A site-to-site VPN tunnel","TLS between two microservices"],answer:0,explanation:"At rest = stored data. The others protect data moving across a network."},{lesson:"cost-management",prompt:"Pricing Calculator vs Cost Management — which is true?",options:["The Pricing Calculator estimates before you deploy; Cost Management tracks actual spend after","Cost Management estimates future architectures without a subscription","The Pricing Calculator sets budgets on live subscriptions","They are the same tool"],answer:0,explanation:"Calculator = before. Cost Management = after."},{lesson:"cost-management",prompt:"Reservation vs savings plan for compute — which is more flexible across VM sizes and regions?",options:["Savings plan for compute","Reservation","Both equally","Neither offers a discount"],answer:0,explanation:"Savings plans commit to spend and apply broadly. Reservations are tied to a specific resource."},{lesson:"governance",prompt:"Azure Policy vs Azure RBAC — which is correct?",options:["Policy controls what resources and configurations are allowed; RBAC controls who can perform actions","Policy controls who can sign in; RBAC controls regions","Both only apply to storage","RBAC can block a region for everyone, including Owners"],answer:0,explanation:"Policy = what. RBAC = who."},{lesson:"governance",prompt:"CanNotDelete vs ReadOnly lock — which still allows changing a resource's settings?",options:["CanNotDelete","ReadOnly","Both","Neither"],answer:0,explanation:"CanNotDelete blocks deletion only. ReadOnly blocks deletion and changes."},{lesson:"governance",prompt:"Microsoft Purview vs Azure Policy — which governs data rather than resource configuration?",options:["Microsoft Purview","Azure Policy","Resource locks","Azure Advisor"],answer:0,explanation:"Purview discovers, classifies, and governs data. Policy governs resource configuration."},{lesson:"manage-and-deploy",prompt:"Azure CLI vs Azure PowerShell — which is true?",options:["Azure CLI uses az commands; Azure PowerShell uses cmdlets like New-AzVM. Both can do the same Azure tasks","Only Azure PowerShell can create VMs","Azure CLI only runs on Windows","Azure PowerShell only works in the portal"],answer:0,explanation:"Same capabilities, different syntax. Pick the one your team knows."},{lesson:"manage-and-deploy",prompt:"ARM vs ARM templates — which is true?",options:["ARM is the deployment and management service; ARM templates are JSON files describing what to deploy","ARM templates are the management service; ARM is a JSON file","ARM is only used by the Azure portal","ARM templates can only be deployed once"],answer:0,explanation:"Every request goes through Azure Resource Manager. Templates are the infrastructure-as-code input."},{lesson:"monitoring",prompt:"Azure Service Health vs Azure Monitor — which is true?",options:["Service Health reports Azure platform issues affecting you; Azure Monitor collects metrics and logs from your resources and apps","Azure Monitor only shows global Azure outages","Service Health queries your application logs with KQL","They are the same service"],answer:0,explanation:"Service Health = Microsoft's side. Monitor = your telemetry."},{lesson:"monitoring",prompt:"Azure Advisor vs Microsoft Defender for Cloud — which is the dedicated security posture and workload protection service?",options:["Microsoft Defender for Cloud","Azure Advisor","Azure Service Health","Log Analytics"],answer:0,explanation:"Advisor gives security tips among five categories; Defender for Cloud is the specialist security service."}]),n=function(e,o){let s=[...e];for(let e of o){let o=s.findLastIndex(o=>o.lesson===e.lesson);s.splice(o+1||s.length,0,e)}return s}(s("l3",[{lesson:"cloud-computing",prompt:"Which of these is NOT a typical characteristic of cloud computing?",options:["Large up-front hardware purchases","On-demand self-service","Broad network access","Metered, pay-for-what-you-use billing"],answer:0,explanation:"Cloud replaces up-front hardware purchases with metered, on-demand services."},{lesson:"cloud-computing",kind:"yesno",prompt:"For each statement, choose Yes if it is true.",options:["In the consumption-based model you pay for the resources you use.","Pay-as-you-go pricing requires a 3-year commitment.","Serverless computing means no servers exist anywhere."],answer:0,answers:[0],explanation:"Consumption-based = pay for what you use. Pay-as-you-go has no commitment. Serverless still runs on servers; you just do not manage them."},{lesson:"cloud-computing",prompt:"Which cloud pricing model is BEST for a workload that runs 24/7 for the next three years without changing?",options:["Reserved capacity","Spot","Pay-as-you-go","Free tier only"],answer:0,explanation:"Steady, long-term workloads get the biggest discount with reservations."},{lesson:"cloud-computing",kind:"complete",prompt:"Moving from on-premises servers to cloud services generally shifts IT spending from ____.",options:["CapEx to OpEx","OpEx to CapEx","OpEx to licensing","free to CapEx"],answer:0,explanation:"You stop buying hardware (CapEx) and start paying for usage (OpEx)."},{lesson:"cloud-computing",prompt:"In serverless computing, how is the customer typically billed?",options:["For the execution time and resources consumed when code runs","A fixed monthly fee per physical server","Per employee in the company","A one-time license fee"],answer:0,explanation:"Serverless is billed by consumption — executions, duration, memory."},{lesson:"cloud-computing",prompt:"Which is an advantage of the consumption-based model?",options:["No need to buy capacity for peak demand in advance","Bills are identical every month no matter what","You own the physical hardware","No internet connection is required"],answer:0,explanation:"You can add capacity when needed and pay only for that usage."},{lesson:"cloud-computing",prompt:"A company wants to test a new app idea for one week, then delete everything. Which cloud characteristic makes this cheap?",options:["On-demand resources billed only while they exist","Mandatory 3-year reservations","Buying servers and reselling them","Private cloud hardware"],answer:0,explanation:"Create, use, delete — and stop paying. No hardware is left behind."},{lesson:"shared-responsibility",prompt:"In IaaS, which of these is the customer's responsibility?",options:["The guest operating system","The physical host","The datacenter network","The building's power supply"],answer:0,explanation:"With IaaS you manage the OS and everything above it."},{lesson:"shared-responsibility",kind:"multi",prompt:"Which TWO responsibilities always remain with the customer, regardless of service type?",options:["Information and data","Accounts and identities","Physical network","Physical hosts"],answer:0,answers:[0,1],explanation:"Data and identities (plus devices) are always the customer's. Physical layers are always Microsoft's."},{lesson:"shared-responsibility",prompt:"In SaaS, which responsibility does Microsoft take on that it does NOT take on in IaaS?",options:["The application itself","The customer's data classification","User accounts","End-user devices"],answer:0,explanation:"In SaaS the provider runs the application. Data, accounts, and devices stay with the customer."},{lesson:"shared-responsibility",prompt:"Which statement BEST describes the shared responsibility model?",options:["Security duties are split between the cloud provider and the customer, and the split depends on the service type","Microsoft is responsible for everything once you move to Azure","The customer is responsible for everything, including the datacenter","It only applies to SaaS"],answer:0,explanation:"Responsibility shifts toward the provider as you move from IaaS to PaaS to SaaS."},{lesson:"shared-responsibility",kind:"yesno",prompt:"For each statement, choose Yes if it is true.",options:["In PaaS, the customer patches the operating system.","In every model, Microsoft is responsible for physical security.","In SaaS, the customer is responsible for who can access their data."],answer:0,answers:[1,2],explanation:"PaaS OS patching is Microsoft's. Physical is always Microsoft's. Access to data is always the customer's."},{lesson:"shared-responsibility",prompt:"Which responsibility is shared between Microsoft and the customer in PaaS?",options:["Network controls","Physical datacenter","Customer data","Physical hosts"],answer:0,explanation:"Network controls, identity infrastructure, and applications are shared in PaaS; the platform provides features, you configure them."},{lesson:"shared-responsibility",prompt:"On-premises, who is responsible for the hypervisor, OS, application, and data?",options:["The customer","Microsoft","The hardware vendor","A regulator"],answer:0,explanation:"On-premises, the customer owns every layer."},{lesson:"cloud-models",prompt:"Which model is BEST for a company that wants no hardware to maintain and pays only for what it uses?",options:["Public cloud","Private cloud","On-premises datacenter","Dedicated colocation"],answer:0,explanation:"Public cloud: provider owns the hardware; customer pays for usage."},{lesson:"cloud-models",prompt:"Which is a typical use case for a private cloud?",options:["Strict regulatory requirements demanding dedicated hardware the organization controls","A short marketing campaign website","A student testing a free app","Bursting extra capacity for a weekend"],answer:0,explanation:"Private cloud suits organizations that need full control and dedicated infrastructure."},{lesson:"cloud-models",kind:"yesno",prompt:"For each statement, choose Yes if it is true.",options:["A hybrid cloud can let workloads move between on-premises and public cloud.","A private cloud requires no up-front investment.","In a public cloud, many customers share the provider's hardware."],answer:0,answers:[0,2],explanation:"Hybrid gives flexibility; private cloud needs hardware investment; public cloud is multi-tenant."},{lesson:"cloud-models",prompt:"A company uses Azure for analytics and Google Cloud for its email. Which term applies?",options:["Multi-cloud","Private cloud","Hybrid cloud only","SaaS-only"],answer:0,explanation:"Multiple public cloud providers = multi-cloud."},{lesson:"cloud-models",prompt:"Which service helps manage a hybrid and multi-cloud environment from Azure?",options:["Azure Arc","Azure Data Box","Azure Files","Azure Virtual Desktop"],answer:0,explanation:"Azure Arc extends Azure management to resources running anywhere."},{lesson:"cloud-models",prompt:"Which model gives the organization the MOST responsibility for hardware?",options:["Private cloud","Public cloud","Hybrid cloud","Multi-cloud"],answer:0,explanation:"Private cloud hardware is owned and maintained by (or for) the organization."},{lesson:"cloud-models",kind:"complete",prompt:"Running extra workloads in the public cloud when on-premises capacity runs out is a typical ____ cloud scenario.",options:["hybrid","private","sovereign","serverless"],answer:0,explanation:"Cloud bursting connects on-premises and public cloud — hybrid."},{lesson:"cloud-benefits",prompt:"An app's SLA promises 99.99% uptime. Which cloud benefit does this mainly describe?",options:["High availability","Elasticity","Governance","Cost predictability"],answer:0,explanation:"SLAs describe availability guarantees."},{lesson:"cloud-benefits",kind:"multi",prompt:"Which TWO are examples of predictability in the cloud?",options:["Forecasting next month's spend with budgets","Autoscaling to keep response times consistent","Assigning the Owner role","Deleting a resource group"],answer:0,answers:[0,1],explanation:"Cost predictability (forecasting) and performance predictability (consistent response times)."},{lesson:"cloud-benefits",prompt:"Which benefit lets you manage resources from anywhere using the portal, CLI, or APIs?",options:["Manageability","Sustainability","Sovereignty","Vertical scaling"],answer:0,explanation:"Management of the cloud — portal, CLI, APIs, automation — is manageability."},{lesson:"cloud-benefits",prompt:"Which statement about sustainability in the cloud is correct?",options:["Shared, efficient datacenters can lower energy use per workload compared with many small server rooms","Cloud workloads have no environmental impact","Sustainability means you can never delete resources","Only private clouds can be sustainable"],answer:0,explanation:"High utilization, efficient cooling, and renewable energy reduce the footprint per workload."},{lesson:"cloud-benefits",prompt:"Microsoft keeps platform security up to date, and you can apply policies across all resources. Which benefit pair is this?",options:["Security and governance","Elasticity and scalability","CapEx and OpEx","IaaS and SaaS"],answer:0,explanation:"Built-in security plus centrally enforced standards = security and governance."},{lesson:"cloud-benefits",kind:"yesno",prompt:"For each statement, choose Yes if it is true.",options:["Scaling up means adding more instances.","Elasticity can reduce cost by removing unused capacity.","High availability and scalability are the same thing."],answer:0,answers:[1],explanation:"Scaling up = bigger instance. Elasticity scales in to save money. HA (uptime) and scalability (capacity) differ."},{lesson:"cloud-benefits",prompt:"A company deploys its app in two regions so it can recover if one region fails. Which benefit is this?",options:["Reliability","Vertical scaling","Cost predictability","Manageability"],answer:0,explanation:"Recovering from failure and continuing to function is reliability."},{lesson:"cloud-service-types",prompt:"Which service type is BEST for developers who want to focus only on writing and deploying code?",options:["PaaS","IaaS","SaaS","On-premises"],answer:0,explanation:"PaaS manages infrastructure and runtime for developers."},{lesson:"cloud-service-types",kind:"multi",prompt:"Which TWO are examples of PaaS in Azure?",options:["Azure App Service","Azure SQL Database","Azure Virtual Machines","Microsoft 365"],answer:0,answers:[0,1],explanation:"App Service and SQL Database are managed platforms. VMs are IaaS; Microsoft 365 is SaaS."},{lesson:"cloud-service-types",prompt:"Which service type requires the customer to manage the most?",options:["IaaS","PaaS","SaaS","They are all equal"],answer:0,explanation:"IaaS leaves OS, middleware, runtime, apps, and data to the customer."},{lesson:"cloud-service-types",prompt:"A company wants a ready-made HR system it can use right away with no installation. Which service type?",options:["SaaS","PaaS","IaaS","Serverless"],answer:0,explanation:"Ready-made software you just use = SaaS."},{lesson:"cloud-service-types",kind:"complete",prompt:"A lift-and-shift migration of existing servers to the cloud with no code changes is a typical ____ use case.",options:["IaaS","PaaS","SaaS","serverless"],answer:0,explanation:"Moving VMs as-is = IaaS."},{lesson:"cloud-service-types",prompt:"Which is a typical use case for PaaS?",options:["A development framework for building and deploying cloud apps","Using hosted email","Running a custom OS kernel module","Buying a server rack"],answer:0,explanation:"PaaS provides frameworks, analytics, and managed runtimes for building apps."},{lesson:"cloud-service-types",kind:"yesno",prompt:"For each statement, choose Yes if it is true.",options:["IaaS gives the customer the most control over the operating system.","In SaaS, the customer installs and patches the application.","Azure Functions sits toward the PaaS end of the spectrum."],answer:0,answers:[0,2],explanation:"IaaS = most control. SaaS apps are maintained by the provider. Functions is serverless PaaS-style compute."},{lesson:"regions-and-zones",prompt:"Why do some Azure services require you to choose a region?",options:["So you control where the resource is physically hosted, for latency and data residency","Because regions determine your RBAC role","Because regions decide which tags you can use","Regions are only used for billing addresses"],answer:0,explanation:"Region choice affects latency, residency, available services, and price."},{lesson:"regions-and-zones",kind:"yesno",prompt:"For each statement, choose Yes if it is true.",options:["Every Azure region supports availability zones.","Availability zones are connected by high-speed private networks.","A region pair is usually in the same geography."],answer:0,answers:[1,2],explanation:"Not all regions have zones. Zones are linked by fast private fiber. Most pairs stay in the same geography."},{lesson:"regions-and-zones",prompt:"Which statement about Azure datacenters is correct?",options:["They are facilities with racks of servers, their own power, cooling, and networking, grouped into regions","Customers can visit and touch their servers","Each customer gets a private datacenter","Datacenters are always in the customer's country"],answer:0,explanation:"Datacenters are the physical building blocks; customers do not access them directly."},{lesson:"regions-and-zones",prompt:"Which type of service, such as Microsoft Entra ID, is available globally and is not tied to a single region?",options:["Non-regional (global) service","Zonal service","Zone-redundant service","Sovereign service"],answer:0,explanation:"Some services are global and resilient to region-wide outages, like Entra ID and Azure DNS."},{lesson:"regions-and-zones",prompt:"Azure Government is designed for which customers?",options:["US government agencies and their partners","Any company that wants lower prices","Customers in China","Students only"],answer:0,explanation:"Azure Government is a sovereign cloud for US government needs. China uses Azure operated by 21Vianet."},{lesson:"regions-and-zones",kind:"complete",prompt:"To protect a VM-based app from a single datacenter failure in one region, deploy VMs across ____.",options:["availability zones","resource groups","tags","management groups"],answer:0,explanation:"Zones are physically separate datacenters within the region."},{lesson:"regions-and-zones",prompt:"Which is a reason two regions are paired?",options:["To provide a partner region for disaster recovery and geo-replication","To share a single billing account","To merge their availability zones","To allow tags to work"],answer:0,explanation:"Pairs support DR: geo-replication targets, staggered updates, and prioritized recovery."},{lesson:"resource-hierarchy",prompt:"What is the correct order of the Azure hierarchy from top to bottom?",options:["Management groups → subscriptions → resource groups → resources","Subscriptions → management groups → resources → resource groups","Resource groups → subscriptions → management groups → resources","Resources → resource groups → subscriptions → management groups"],answer:0,explanation:"MG → subscription → RG → resource."},{lesson:"resource-hierarchy",kind:"multi",prompt:"Which TWO statements about subscriptions are true?",options:["A subscription is a billing boundary","A subscription is an access control boundary","A subscription can be nested inside a resource group","A subscription can only contain one resource"],answer:0,answers:[0,1],explanation:"Subscriptions separate billing and access. They contain many resource groups."},{lesson:"resource-hierarchy",prompt:"Can you move a resource from one resource group to another?",options:["Yes, many resources can be moved between resource groups","No, never","Only by deleting and recreating it","Only between regions"],answer:0,explanation:"Most resources support moving between resource groups (and subscriptions)."},{lesson:"resource-hierarchy",kind:"yesno",prompt:"For each statement, choose Yes if it is true.",options:["Resource groups can be nested inside other resource groups.","Permissions assigned at a resource group apply to resources inside it.","A resource can exist in only one resource group at a time."],answer:0,answers:[1,2],explanation:"No nesting; permissions inherit; one resource group per resource."},{lesson:"resource-hierarchy",prompt:"What does the Microsoft Learn sandbox provide?",options:["A temporary, free subscription for completing Learn exercises","A permanent production subscription","A physical server","A paid support plan"],answer:0,explanation:"The sandbox is a short-lived subscription created for Learn modules and cleaned up afterward."},{lesson:"resource-hierarchy",prompt:"What is an Azure resource?",options:["A manageable item such as a VM, storage account, or virtual network","A billing account only","A management group","An Azure region"],answer:0,explanation:"Resources are the basic building blocks you create and manage."},{lesson:"resource-hierarchy",prompt:"All subscriptions in a directory share a single top-level management group. What is it called?",options:["The root management group","The tenant resource group","The primary subscription","The global region"],answer:0,explanation:"Each directory has one root management group at the top of the hierarchy."},{lesson:"compute",prompt:"Which compute option gives the MOST control over the operating system?",options:["Azure Virtual Machines","Azure Functions","Azure App Service","Azure Container Apps"],answer:0,explanation:"VMs are IaaS — you control the OS."},{lesson:"compute",kind:"multi",prompt:"Which TWO resources are required to create a typical Azure VM, besides the VM size?",options:["A disk for the OS","A network interface on a virtual network","An Azure Policy","A management group"],answer:0,answers:[0,1],explanation:"A VM needs an OS disk and a NIC on a VNet/subnet. Policies and management groups are optional governance."},{lesson:"compute",prompt:"Which hosting option is designed for web apps, REST APIs, and mobile back ends without managing servers?",options:["Azure App Service","Azure Virtual Desktop","Azure Data Box","Azure Arc"],answer:0,explanation:"App Service is PaaS for web apps and APIs."},{lesson:"compute",prompt:"What is a benefit of containers compared with VMs?",options:["They are lightweight and start quickly because they do not include a full guest OS","They always provide more OS control","They require a dedicated physical server each","They cannot be scaled"],answer:0,explanation:"Containers share the host kernel, so they are small and fast."},{lesson:"compute",kind:"yesno",prompt:"For each statement, choose Yes if it is true.",options:["Azure Functions can be triggered by events such as HTTP requests or queue messages.","Azure Virtual Desktop is used to host public websites.","VM Scale Sets can automatically increase the number of VMs based on demand."],answer:0,answers:[0,2],explanation:"Functions are event-driven; AVD is desktops; scale sets autoscale."},{lesson:"compute",prompt:"Which service is the platform for data scientists to train, deploy, and manage their own machine learning models?",options:["Azure Machine Learning","Azure AI services","Azure IoT Hub","Azure Functions"],answer:0,explanation:"Azure Machine Learning is for building your own models. AI services are prebuilt APIs."},{lesson:"compute",kind:"complete",prompt:"An availability set protects VMs by spreading them across fault domains and ____ domains.",options:["update","billing","DNS","identity"],answer:0,explanation:"Fault domains = separate racks/power; update domains = staggered host maintenance."},{lesson:"networking",prompt:"Which capability lets resources in an Azure VNet communicate with each other by default?",options:["Resources in the same VNet can communicate privately","They must use ExpressRoute","They must use public IPs","They cannot communicate without Azure Firewall"],answer:0,explanation:"Resources in a VNet can talk to each other over private IPs by default."},{lesson:"networking",kind:"multi",prompt:"Which TWO can connect an on-premises network to an Azure VNet?",options:["Azure VPN Gateway","Azure ExpressRoute","Azure DNS","Azure Advisor"],answer:0,answers:[0,1],explanation:"VPN Gateway (over the internet) and ExpressRoute (private) both provide hybrid connectivity."},{lesson:"networking",prompt:"What does Azure DNS do?",options:["Hosts DNS domains and resolves names using Azure infrastructure","Encrypts data at rest","Assigns RBAC roles","Stores blobs"],answer:0,explanation:"Azure DNS hosts your DNS zones and resolves names, managed with your other Azure resources."},{lesson:"networking",prompt:"Which feature filters traffic to and from resources by port and IP address on a subnet or NIC?",options:["Network security group","Azure DNS","VNet peering","Azure Data Box"],answer:0,explanation:"NSGs contain allow/deny security rules."},{lesson:"networking",kind:"yesno",prompt:"For each statement, choose Yes if it is true.",options:["VNet peering traffic travels over the Microsoft backbone, not the public internet.","ExpressRoute connections go over the public internet.","A single VNet can span multiple Azure regions."],answer:0,answers:[0],explanation:"Peering uses the backbone. ExpressRoute is private. A VNet lives in one region."},{lesson:"networking",prompt:"Which service protects public-facing apps from distributed denial-of-service attacks?",options:["Azure DDoS Protection","Network security groups","Azure DNS","Azure Key Vault"],answer:0,explanation:"DDoS Protection detects and mitigates volumetric floods."},{lesson:"networking",kind:"complete",prompt:"A VPN Gateway connection from an office network to Azure is called a ____ connection.",options:["site-to-site","point-to-site","peer-to-peer","zone-to-zone"],answer:0,explanation:"Site-to-site connects networks. Point-to-site connects individual devices."},{lesson:"storage",prompt:"Which storage service provides fully managed file shares accessible via SMB or NFS?",options:["Azure Files","Azure Blob Storage","Azure Queue Storage","Azure Disk Storage"],answer:0,explanation:"Azure Files offers SMB/NFS file shares in the cloud."},{lesson:"storage",kind:"multi",prompt:"Which TWO redundancy options copy data to a secondary region?",options:["GRS","GZRS","LRS","ZRS"],answer:0,answers:[0,1],explanation:"Geo options (GRS, GZRS) replicate to a second region. LRS and ZRS stay in one region."},{lesson:"storage",prompt:"What must be true about a storage account name?",options:["It must be globally unique across Azure","It must match the resource group name","It can contain spaces","It must start with the region name"],answer:0,explanation:"The name forms a public URL (for example name.blob.core.windows.net), so it must be globally unique."},{lesson:"storage",prompt:"Which blob access tier is online but meant for data rarely accessed and kept at least 90 days?",options:["Cold","Hot","Archive","Premium"],answer:0,explanation:"Cold is online, cheaper than Cool to store, meant for rarely accessed data."},{lesson:"storage",kind:"yesno",prompt:"For each statement, choose Yes if it is true.",options:["Data in the Archive tier can be read instantly.","ZRS keeps copies across availability zones in one region.","Azure Disk Storage provides disks for VMs."],answer:0,answers:[1,2],explanation:"Archive must be rehydrated (hours). ZRS spans zones. Disks attach to VMs."},{lesson:"storage",prompt:"Which service stores structured NoSQL data as key/attribute entities?",options:["Azure Table Storage","Azure Queue Storage","Azure Files","Azure Disk Storage"],answer:0,explanation:"Table Storage is a NoSQL key-attribute store."},{lesson:"storage",kind:"complete",prompt:"To keep a Windows file server on-premises while syncing it with an Azure file share, use ____.",options:["Azure File Sync","Azure Data Box","Azure Migrate","AzCopy"],answer:0,explanation:"Azure File Sync caches Azure Files on Windows Server with optional cloud tiering."},{lesson:"identity",prompt:"Which is a function of Microsoft Entra ID?",options:["Authenticating users and managing access to apps","Storing virtual machine disks","Estimating Azure costs","Replicating storage between regions"],answer:0,explanation:"Entra ID handles identities, sign-in, SSO, and app access."},{lesson:"identity",kind:"multi",prompt:"Which TWO are passwordless authentication methods supported by Microsoft Entra ID?",options:["Windows Hello for Business","FIDO2 security keys","A longer password","A shared admin account"],answer:0,answers:[0,1],explanation:"Passwordless options include Windows Hello for Business, Microsoft Authenticator, and FIDO2 keys."},{lesson:"identity",prompt:"Which feature evaluates signals such as user, location, and device before granting access?",options:["Conditional Access","Azure Policy","Resource locks","Azure DNS"],answer:0,explanation:"Conditional Access uses signals to allow, block, or require MFA."},{lesson:"identity",kind:"yesno",prompt:"For each statement, choose Yes if it is true.",options:["SSO reduces the number of passwords users must remember.","MFA requires only a password.","External identities let guests sign in with their own credentials."],answer:0,answers:[0,2],explanation:"SSO = fewer passwords. MFA = more than one factor. Guests use their own identity."},{lesson:"identity",prompt:'Which is an example of "something you have" in MFA?',options:["A phone with an authenticator app","A password","A fingerprint","A username"],answer:0,explanation:"Know = password, have = phone/key, are = biometrics."},{lesson:"identity",prompt:"Microsoft Entra Domain Services is MOST useful for which scenario?",options:["Lifting legacy apps that require domain join, LDAP, or Kerberos to Azure without managing domain controllers","Estimating monthly costs","Hosting a public website","Storing images"],answer:0,explanation:"Domain Services provides managed classic directory features."},{lesson:"identity",kind:"complete",prompt:"Microsoft Entra ID was formerly known as ____.",options:["Azure Active Directory","Azure Arc","Azure Advisor","Active Storage"],answer:0,explanation:"Azure AD was renamed Microsoft Entra ID."},{lesson:"security",prompt:"At which scopes can an Azure RBAC role be assigned?",options:["Management group, subscription, resource group, or resource","Only at the subscription","Only at the resource","Only in Entra ID tenants"],answer:0,explanation:"RBAC roles can be assigned at any level of the hierarchy and inherit downward."},{lesson:"security",kind:"multi",prompt:"Which TWO are layers of the defense-in-depth model?",options:["Physical security","Identity and access","Pricing","Tagging"],answer:0,answers:[0,1],explanation:"Layers: physical, identity & access, perimeter, network, compute, application, data."},{lesson:"security",prompt:"Which layer of defense-in-depth is at the center, protected by all the others?",options:["Data","Physical security","Perimeter","Network"],answer:0,explanation:"Data is the innermost layer — the thing attackers want."},{lesson:"security",kind:"yesno",prompt:"For each statement, choose Yes if it is true.",options:["Zero Trust assumes the corporate network is automatically safe.","Defender for Cloud can protect workloads in AWS and Google Cloud.","Key Vault can store TLS/SSL certificates."],answer:0,answers:[1,2],explanation:"Zero Trust trusts no network. Defender for Cloud is multicloud. Key Vault stores certificates."},{lesson:"security",prompt:"Which principle means giving users only the access they need to do their job?",options:["Least privilege","Assume breach","Defense-in-depth","High availability"],answer:0,explanation:"Least privilege limits permissions and scope."},{lesson:"security",prompt:"Which Defender for Cloud feature summarizes how secure your environment is?",options:["Secure Score","Service Health","Pricing Calculator","Resource Health"],answer:0,explanation:"Secure Score measures posture; recommendations raise it."},{lesson:"security",kind:"complete",prompt:"Data stored on disks in Azure Storage is protected by encryption ____.",options:["at rest","in transit","in memory only","on the client only"],answer:0,explanation:"Stored data = encryption at rest, enabled by default in Azure Storage."},{lesson:"cost-management",kind:"multi",prompt:"Which TWO factors affect the cost of Azure resources?",options:["The Azure region","The resource type and size","The resource group's name","The number of tags"],answer:0,answers:[0,1],explanation:"Region, type/SKU, consumption, and egress drive cost. Names and tag counts do not."},{lesson:"cost-management",prompt:"What can Microsoft Cost Management budgets do?",options:["Alert you when spending reaches thresholds you set","Prevent resource deletion","Assign RBAC roles","Block sign-ins from other countries"],answer:0,explanation:"Budgets track spend and send alerts (and can trigger automation)."},{lesson:"cost-management",kind:"yesno",prompt:"For each statement, choose Yes if it is true.",options:["Inbound data transfer into Azure is generally free.","Tags are automatically inherited by every resource in a resource group.","The Pricing Calculator requires an existing deployment to work."],answer:0,answers:[0],explanation:"Inbound is generally free. Tags are not inherited by default (Policy can enforce it). The calculator works before deployment."},{lesson:"cost-management",prompt:"Which purchase option lets you reuse existing on-premises Windows Server licenses in Azure?",options:["Azure Hybrid Benefit","Spot pricing","Pay-as-you-go","Savings plan for compute"],answer:0,explanation:"Hybrid Benefit applies existing licenses with Software Assurance."},{lesson:"cost-management",prompt:"Which tool would you use to compare costs of running your current on-premises servers versus in Azure?",options:["An Azure Migrate business case","Azure Service Health","Microsoft Purview","Azure DNS"],answer:0,explanation:"Azure Migrate builds business cases comparing on-premises and Azure costs (the standalone TCO Calculator was retired)."},{lesson:"cost-management",prompt:"What happens to the cost of a VM that is stopped (deallocated) in Azure?",options:["Compute charges stop, but storage for its disks is still billed","All charges stop, including disks","Charges double","Nothing changes"],answer:0,explanation:"Deallocation releases compute; managed disks still incur storage costs."},{lesson:"cost-management",kind:"complete",prompt:"To group costs by project across several subscriptions, apply ____ to resources.",options:["tags","locks","NSGs","availability zones"],answer:0,explanation:"Tags let Cost Management group and filter spend by any label."},{lesson:"governance",prompt:"Which Azure Policy effect blocks a non-compliant resource from being created?",options:["Deny","Audit","Append","Disabled"],answer:0,explanation:"Deny prevents the request. Audit only logs a warning."},{lesson:"governance",kind:"multi",prompt:"Which TWO are capabilities of Microsoft Purview?",options:["Discovering and classifying sensitive data","Data lineage and a data catalog","Assigning VM sizes","Creating virtual networks"],answer:0,answers:[0,1],explanation:"Purview discovers, classifies, catalogs, and tracks data lineage."},{lesson:"governance",kind:"yesno",prompt:"For each statement, choose Yes if it is true.",options:["A resource lock applies to all users, including Owners.","Azure Policy can evaluate resources that already exist.","The Service Trust Portal configures compliance settings on your resources."],answer:0,answers:[0,1],explanation:"Locks apply to everyone. Policy evaluates existing resources. Service Trust Portal is a library of documents, not a config tool."},{lesson:"governance",prompt:"Who can remove a resource lock?",options:["A user with permission to manage locks, such as an Owner or User Access Administrator","Any Reader","Nobody, ever","Only Microsoft support"],answer:0,explanation:"Removing a lock requires Microsoft.Authorization permissions, typically Owner or User Access Administrator."},{lesson:"governance",prompt:"Where can policies be assigned in Azure?",options:["Management group, subscription, or resource group","Only individual resources","Only Entra ID users","Only in the Pricing Calculator"],answer:0,explanation:"Policy assignments inherit downward from where they are assigned."},{lesson:"governance",prompt:"What type of content is available on the Service Trust Portal?",options:["Independent audit reports, compliance guides, and whitepapers about Microsoft cloud services","Your subscription's invoices","Real-time CPU metrics","Virtual machine images"],answer:0,explanation:"The Service Trust Portal publishes Microsoft's trust and compliance documentation."},{lesson:"governance",kind:"complete",prompt:"To prevent a production database from being deleted while still allowing configuration changes, apply a ____ lock.",options:["CanNotDelete","ReadOnly","Policy","Tag"],answer:0,explanation:"CanNotDelete blocks only deletion."},{lesson:"manage-and-deploy",prompt:"Which tool is a web-based, unified console for managing Azure resources with a graphical interface?",options:["Azure portal","Azure CLI","Azure PowerShell","Bicep"],answer:0,explanation:"The Azure portal is the browser GUI."},{lesson:"manage-and-deploy",kind:"multi",prompt:"Which TWO are benefits of using ARM templates?",options:["Declarative syntax describing the desired state","Repeatable deployments with consistent results","Automatic MFA for every user","Free outbound bandwidth"],answer:0,answers:[0,1],explanation:"Templates are declarative and repeatable infrastructure as code."},{lesson:"manage-and-deploy",kind:"yesno",prompt:"For each statement, choose Yes if it is true.",options:["Azure PowerShell and Azure CLI can both be used in Cloud Shell.","Every request from the portal, CLI, and PowerShell goes through Azure Resource Manager.","Azure Arc can only manage resources running in Azure."],answer:0,answers:[0,1],explanation:"Cloud Shell includes both tools. ARM is the single control plane. Arc manages resources outside Azure."},{lesson:"manage-and-deploy",prompt:"What is infrastructure as code (IaC)?",options:["Managing and provisioning infrastructure through code files rather than manual processes","Writing application code inside a VM","A type of storage redundancy","A billing model"],answer:0,explanation:"IaC = infrastructure described in code, deployable repeatedly."},{lesson:"manage-and-deploy",prompt:"Bicep files are deployed through which service?",options:["Azure Resource Manager","Azure Advisor","Azure DNS","Azure Service Health"],answer:0,explanation:"Bicep compiles to ARM templates and deploys via ARM."},{lesson:"manage-and-deploy",prompt:"Which tool would a Linux administrator most likely script with, using commands like az vm create?",options:["Azure CLI","Azure PowerShell","Azure portal","Azure Data Box"],answer:0,explanation:"az commands are the Azure CLI."},{lesson:"manage-and-deploy",kind:"complete",prompt:"Azure Resource Manager lets you apply access control, locks, and tags to resources because it is Azure's ____.",options:["management layer","storage tier","identity provider","pricing tool"],answer:0,explanation:"ARM is the deployment and management service — the control plane."},{lesson:"monitoring",kind:"multi",prompt:"Which TWO are Azure Advisor recommendation categories?",options:["Reliability","Operational excellence","Sovereignty","Licensing"],answer:0,answers:[0,1],explanation:"Advisor categories: Reliability, Security, Performance, Operational excellence, Cost."},{lesson:"monitoring",prompt:"Which Azure Monitor feature sends notifications when a metric or log condition is met?",options:["Alerts","Tags","Locks","Blueprints"],answer:0,explanation:"Azure Monitor alerts notify or trigger actions on conditions."},{lesson:"monitoring",kind:"yesno",prompt:"For each statement, choose Yes if it is true.",options:["Azure Monitor can collect data from on-premises and other clouds.","Log Analytics uses Kusto Query Language (KQL).","Azure Advisor automatically applies all its recommendations without your approval."],answer:0,answers:[0,1],explanation:"Monitor is hybrid-capable. Log Analytics uses KQL. Advisor recommends; you decide."},{lesson:"monitoring",prompt:"Where do Azure Monitor logs live so you can query them?",options:["A Log Analytics workspace","A resource lock","A storage queue","A management group"],answer:0,explanation:"Logs are stored and queried in Log Analytics workspaces."},{lesson:"monitoring",prompt:"Which service tells you about Azure incidents and planned maintenance that affect YOUR subscriptions and regions?",options:["Azure Service Health","Azure status page","Azure Advisor","Application Insights"],answer:0,explanation:"Service Health is the personalized view; Azure status is the public global view."},{lesson:"monitoring",prompt:"Application Insights can monitor apps running where?",options:["In Azure, on-premises, or in other clouds","Only in Azure Functions","Only on Azure VMs","Only in Microsoft 365"],answer:0,explanation:"Application Insights works wherever the app runs, via its SDK or agents."},{lesson:"monitoring",kind:"complete",prompt:"Numerical values collected at regular intervals, such as CPU percentage, are called ____ in Azure Monitor.",options:["metrics","logs","tags","alerts"],answer:0,explanation:"Metrics are numbers over time; logs are event records."}]),s("l3m",[{lesson:"cloud-models",kind:"match",prompt:"Match each description to the cloud model.",categories:["Public cloud","Private cloud","Hybrid cloud"],options:["Resources owned by a provider and shared by many organizations, with pay-as-you-go pricing","Resources used exclusively by one organization, which keeps full control","An on-premises datacenter connected to Azure so workloads and data can move between them"],answer:0,answers:[0,1,2],explanation:"Shared provider infrastructure = public. Exclusive use by one organization = private. On-premises plus public cloud working together = hybrid."},{lesson:"regions-and-zones",kind:"order",prompt:"Arrange these Azure physical infrastructure terms from the smallest to the largest.",options:["Datacenter","Availability zone","Region","Geography"],answer:0,explanation:"An availability zone is one or more datacenters with independent power, cooling, and networking. A region contains multiple datacenters (usually three or more zones). A geography contains one or more regions and respects data residency boundaries."},{lesson:"compute",kind:"match",prompt:"Match each requirement to the Azure compute option.",categories:["Azure Virtual Machines","Azure Container Instances","Azure Functions","Azure Virtual Desktop"],options:["Full control of the operating system for a legacy application","Run a single container quickly without managing servers or an orchestrator","Run a small piece of code when a message arrives, billed only when it runs","Give remote workers a Windows desktop hosted in Azure"],answer:0,answers:[0,1,2,3],explanation:"VMs = IaaS with OS control. ACI = the simplest way to run a container. Functions = event-driven serverless code. Azure Virtual Desktop = desktop and app virtualization."},{lesson:"security",kind:"match",prompt:"Match each control to the defense-in-depth layer it belongs to.",categories:["Physical security","Identity and access","Network","Data"],options:["Biometric access and guards at datacenter doors","Multifactor authentication for administrators","Network security groups that filter traffic between subnets","Encrypting a database at rest"],answer:0,answers:[0,1,2,3],explanation:"Defense in depth stacks layers: physical, identity and access, perimeter, network, compute, application, and data. Each control slows an attacker at its own layer."}])),r=s("l4",[{lesson:"cloud-computing",prompt:"A research lab runs genome analysis jobs that can be paused and resumed. Budget is the top priority; finishing time is flexible. Which compute purchase option is BEST?",options:["Spot VMs","Reserved instances for 3 years","Pay-as-you-go on-demand VMs","Dedicated hosts"],answer:0,explanation:"Interruptible + cheapest = Spot. Reservations suit steady 24/7 workloads.",trap:"Reservations are cheap too, but they assume the workload runs constantly for years."},{lesson:"cloud-computing",prompt:"A startup's image-resizing code runs a few hundred times a day when users upload photos. They want no idle cost and no servers. Which model fits BEST?",options:["Serverless (Azure Functions)","A reserved VM","A VM Scale Set with minimum 2 instances","Azure Virtual Desktop"],answer:0,explanation:"Event-driven, sporadic, no idle cost = serverless.",trap:"A scale set with a minimum of 2 instances still costs money when idle."},{lesson:"shared-responsibility",prompt:"A company uses Azure SQL Database. A developer accidentally grants a public firewall rule to 0.0.0.0–255.255.255.255. Who is responsible for this misconfiguration?",options:["The customer","Microsoft, because SQL Database is PaaS","The internet provider","Nobody — PaaS has no network settings"],answer:0,explanation:"PaaS removes OS and engine patching, but access and network configuration of your database are still yours.",trap:"PaaS does not mean Microsoft configures your firewall rules."},{lesson:"shared-responsibility",prompt:"Which task does the customer still own for a Windows VM in Azure but NOT for a web app on Azure App Service?",options:["Applying OS security updates","Protecting user credentials","Classifying data","Physical server maintenance"],answer:0,explanation:"OS patching is the customer's in IaaS and Microsoft's in PaaS. Credentials and data are always the customer's; physical is always Microsoft's."},{lesson:"cloud-models",prompt:"A bank must keep customer records in its own datacenter by law, but wants to use Azure AI services on anonymized data and manage everything from the Azure portal. What should you recommend?",options:["Hybrid cloud, using Azure Arc to manage the on-premises servers","Public cloud only","Private cloud only, with no Azure services","A sovereign region"],answer:0,explanation:"On-premises data + Azure services = hybrid. Arc gives a single Azure management plane over both.",trap:"A sovereign region is still Azure-hosted — it does not keep data in the bank's own building."},{lesson:"cloud-models",prompt:'A company says: "Our servers are in Azure on a VNet with private IPs, so we are a private cloud." Which statement is correct?',options:["They use the public cloud; private IPs and VNets do not make it a private cloud","They are a private cloud because the IPs are private","They are a hybrid cloud because they use a VNet","They are multi-cloud"],answer:0,explanation:"Private cloud means dedicated infrastructure for one organization. A VNet in Azure is logical isolation in the public cloud."},{lesson:"cloud-benefits",prompt:"A ticketing website crashes when a big concert goes on sale. Upgrading to the biggest VM did not help enough. What should the team do?",options:["Scale out with more instances behind a load balancer and autoscale rules","Scale up to an even bigger VM","Move to a sovereign region","Buy a 3-year reservation"],answer:0,explanation:"Vertical scaling has a ceiling. Horizontal scaling plus elasticity handles big spikes.",trap:"A reservation lowers cost; it does not add capacity."},{lesson:"cloud-benefits",prompt:"Leadership wants every new Azure environment to follow the same naming, region, and tagging rules automatically. Which cloud benefit is this?",options:["Governance","Elasticity","High availability","Vertical scaling"],answer:0,explanation:"Enforcing organizational standards is governance."},{lesson:"cloud-service-types",prompt:"A company is moving a legacy app with a custom Windows service and specific registry settings. It must move in two weeks with no code changes. Which service type?",options:["IaaS","PaaS","SaaS","Serverless"],answer:0,explanation:"No code changes + OS-level customization = lift-and-shift to IaaS VMs.",trap:'PaaS is often "better", but it would require changes to the app.'},{lesson:"cloud-service-types",prompt:"A team builds a new API and wants automatic OS patching, built-in scaling, and deployment slots. Which service type and example fit?",options:["PaaS — Azure App Service","IaaS — Azure Virtual Machines","SaaS — Microsoft 365","IaaS — Azure Virtual Desktop"],answer:0,explanation:"Managed platform features like slots and patching are PaaS."},{lesson:"regions-and-zones",prompt:"An app must survive the failure of an entire datacenter with no data loss and minimal downtime, while staying in one region for data residency. What should you use?",options:["Deploy across availability zones with zone-redundant services","Deploy to a single VM in an availability set","Deploy to the paired region only","Use a sovereign region"],answer:0,explanation:"Zones = separate datacenters in the same region.",trap:"The paired region is a different region — the requirement says stay in one region."},{lesson:"regions-and-zones",prompt:"Which TWO are benefits of Azure region pairs?",kind:"multi",options:["Planned platform updates are rolled out to one region of the pair at a time","During a broad outage, recovery of one region in each pair is prioritized","Region pairs automatically replicate every resource for free","Region pairs are always in the same datacenter"],answer:0,answers:[0,1],explanation:"Staggered updates and prioritized recovery are pair benefits. Replication depends on the service (for example GRS storage) and is not automatic for everything.",trap:"VMs are not automatically copied to the paired region."},{lesson:"resource-hierarchy",prompt:"A company has 40 subscriptions across Sales, IT, and R&D. Security wants one policy applied to all IT subscriptions, and another to all R&D subscriptions. What is the MOST efficient design?",options:["Create management groups for IT and R&D and assign the policies there","Assign each policy to every resource group individually","Put all resources in one resource group","Create one subscription and delete the rest"],answer:0,explanation:"Management groups apply policy and RBAC to many subscriptions at once by inheritance."},{lesson:"resource-hierarchy",prompt:"A dev team creates many short-lived test resources and wants to delete everything for a project in one action when it ends. What should they do?",options:["Put each project's resources in its own resource group and delete the group","Tag the resources and delete the tag","Create a management group per project","Apply a ReadOnly lock"],answer:0,explanation:"Resource groups share a lifecycle — deleting the group deletes everything in it.",trap:"Deleting a tag only removes a label, not the resources."},{lesson:"compute",prompt:"A company needs to run a containerized web app that should scale to zero when idle, with no cluster to manage. Which option is the BEST fit?",options:["Azure Container Apps","Azure Kubernetes Service","A VM with Docker installed","An availability set"],answer:0,explanation:"Container Apps is serverless containers with scale-to-zero. AKS means managing a cluster; a VM means managing an OS."},{lesson:"compute",prompt:"Three VMs must keep running if one server rack loses power or one host is updated, inside a single datacenter. Which feature addresses this specifically?",options:["Availability set","Region pair","VM Scale Set autoscale","Azure Virtual Desktop"],answer:0,explanation:"Availability sets spread VMs across fault domains (racks/power) and update domains (host updates).",trap:"Scale sets can also spread VMs, but the question is about rack and host-update protection — the classic availability set description."},{lesson:"compute",prompt:"A manufacturer wants AI defect detection to run on cameras on the factory floor, even when the internet connection drops. Which service is designed for that?",options:["Azure IoT Edge","Azure IoT Hub only","Azure Virtual Desktop","Azure DNS"],answer:0,explanation:"IoT Edge runs cloud workloads, including AI models, on devices — offline-capable.",trap:"IoT Hub is the cloud-side gateway; it does not run code on the device."},{lesson:"networking",prompt:"Two VNets in different Azure regions must communicate privately with low latency, without gateways or the public internet. What should you use?",options:["Global VNet peering","Site-to-site VPN","ExpressRoute","Azure DNS"],answer:0,explanation:"VNet peering (global, across regions) connects VNets over the Microsoft backbone.",trap:"ExpressRoute connects on-premises to Azure, not VNet to VNet."},{lesson:"networking",prompt:"A company must connect its HQ to Azure with predictable bandwidth and compliance rules forbidding traffic on the public internet. It also wants a backup path if that connection fails. What is the BEST design?",options:["ExpressRoute as primary, with a site-to-site VPN Gateway as backup","Point-to-site VPN for each employee","Public endpoints on every VM","VNet peering to HQ"],answer:0,explanation:"ExpressRoute = private and predictable. A VPN is a common failover path."},{lesson:"networking",prompt:"An internal app's storage account must not be reachable from the internet at all; VMs in the VNet must still reach it. What should you configure?",options:["A private endpoint and disable public network access","An NSG on the storage account's public endpoint only","Azure DNS public zone","DDoS Protection"],answer:0,explanation:"A private endpoint gives the storage account a VNet IP; turning off public access removes the internet path."},{lesson:"storage",prompt:"Compliance requires 7 years of retention for audit logs that are read maybe once a year, and retrieval within 15 hours is acceptable. Which tier minimizes cost?",options:["Archive","Cold","Cool","Hot"],answer:0,explanation:"Archive is cheapest to store; hours of rehydration are acceptable here.",trap:"Cold is cheap and online, but Archive is cheaper when you can wait hours."},{lesson:"storage",prompt:"A read-heavy global app wants its storage to survive a regional outage AND let users read from the secondary region before any failover. Which redundancy option?",options:["RA-GRS or RA-GZRS","GRS","ZRS","LRS"],answer:0,explanation:"RA- variants allow reading the secondary at any time.",trap:"Plain GRS replicates to the secondary, but you cannot read it until failover."},{lesson:"storage",prompt:"A company wants to discover its 300 on-premises VMware VMs, assess Azure readiness and cost, then migrate them. Which service is the hub for this?",options:["Azure Migrate","Azure Data Box","AzCopy","Azure File Sync"],answer:0,explanation:"Azure Migrate discovers, assesses, and migrates servers, databases, and apps."},{lesson:"storage",prompt:"Which TWO tools can copy files into Azure Blob Storage?",kind:"multi",options:["AzCopy","Azure Storage Explorer","Azure Advisor","Microsoft Entra ID"],answer:0,answers:[0,1],explanation:"AzCopy (command line) and Storage Explorer (GUI) both move data to and from Azure Storage."},{lesson:"identity",prompt:"Users should be blocked from signing in from countries where the company does not operate, and must use MFA when on unmanaged devices. Which feature implements both?",options:["Microsoft Entra Conditional Access","Azure Policy","Azure RBAC","Network security groups"],answer:0,explanation:"Conditional Access evaluates signals (location, device, risk) and enforces block or MFA.",trap:"Azure Policy governs resources, not user sign-ins."},{lesson:"identity",prompt:"An old line-of-business app needs Kerberos and domain-joined VMs in Azure. The team does not want to deploy, patch, or back up domain controllers. What should they use?",options:["Microsoft Entra Domain Services","Microsoft Entra ID alone","AD DS on two Azure VMs they manage","Azure Key Vault"],answer:0,explanation:"Entra Domain Services provides managed domain join, Group Policy, LDAP, and Kerberos/NTLM.",trap:"Running AD DS on VMs works but means managing the domain controllers yourself."},{lesson:"identity",prompt:"A partner company's consultants need access to one SharePoint site and one Azure resource group using their own corporate credentials. What should you use?",options:["Entra External ID B2B collaboration (guest users)","Create new member accounts with new passwords","Microsoft Entra Domain Services","Share an admin account"],answer:0,explanation:"B2B guests sign in with their home organization's identity while you control their access."},{lesson:"security",prompt:"A support engineer needs to restart VMs in one resource group only. Following least privilege, what should you assign?",options:["A role that allows VM operations, scoped to that resource group","Owner on the subscription","Contributor on the management group","Global Administrator in Entra ID"],answer:0,explanation:"Least privilege = smallest permissions at the narrowest scope."},{lesson:"security",prompt:"A security team wants one service that assesses Azure, AWS, and on-premises servers against best practices, gives a score, and provides threat protection. Which service?",options:["Microsoft Defender for Cloud","Azure Advisor","Azure Policy","Microsoft Purview"],answer:0,explanation:"Defender for Cloud covers hybrid and multicloud posture management and workload protection."},{lesson:"security",prompt:"Regulators require the company to control and rotate the encryption keys used for data at rest in Azure Storage. What should they use?",options:["Customer-managed keys stored in Azure Key Vault","Microsoft-managed keys only","A resource tag named EncryptionKey","A ReadOnly lock"],answer:0,explanation:"Customer-managed keys in Key Vault let you control, rotate, and revoke keys."},{lesson:"cost-management",prompt:"A finance team sees a large bill increase after a data analytics project started sending results from Azure to an on-premises system. Which cost factor is most likely?",options:["Outbound data transfer (egress)","Inbound data transfer","Resource group count","Number of tags"],answer:0,explanation:"Data leaving Azure is billed; inbound is generally free."},{lesson:"cost-management",prompt:"Each department must see its own monthly Azure spend, even though departments share subscriptions. What is the BEST approach?",options:["Apply a Department tag to resources and group costs by tag in Cost Management","Create a ReadOnly lock per department","Use the Pricing Calculator monthly","Use Azure Service Health"],answer:0,explanation:"Tags + Cost Management cost analysis split shared subscriptions by owner."},{lesson:"cost-management",prompt:'A team "stops" a VM from inside the guest OS to save money, but billing continues. What should they do?',options:["Stop (deallocate) the VM from Azure so compute is released","Delete the resource group's tags","Move the VM to another resource group","Apply a CanNotDelete lock"],answer:0,explanation:"Shutting down inside the OS leaves the VM allocated. Stop (deallocate) in Azure stops compute charges (disks still bill)."},{lesson:"governance",prompt:"An Owner tries to create a VM in East US and is blocked, even though they have full permissions. What is the MOST likely cause?",options:["An Azure Policy that restricts allowed locations","A missing RBAC role","A CanNotDelete lock","An expired Azure Advisor recommendation"],answer:0,explanation:"Policy applies regardless of RBAC role. Owner permissions do not override a Deny policy.",trap:"A CanNotDelete lock blocks deletion, not creation."},{lesson:"governance",prompt:"A ReadOnly lock is applied to a storage account. What could be an unexpected side effect?",options:["Some operations that seem like reads, such as listing storage account keys, are blocked because they are POST operations","The data is deleted","The account moves to the Archive tier","Nothing at all changes"],answer:0,explanation:"ReadOnly blocks all write operations at the management plane, which can include listing keys. Test locks before applying them broadly."},{lesson:"manage-and-deploy",prompt:"A team must deploy the same 30-resource environment to dev, test, and prod with identical settings, and review changes in Git. What should they use?",options:["Infrastructure as code with Bicep or ARM templates","The Azure portal, clicking carefully each time","Azure Advisor","Azure Service Health"],answer:0,explanation:"IaC gives repeatable, version-controlled deployments."},{lesson:"manage-and-deploy",prompt:"You redeploy an ARM template that has already been deployed with no changes. What happens?",options:["Nothing changes — template deployments are idempotent","All resources are duplicated","All resources are deleted and recreated","The deployment always fails"],answer:0,explanation:"Declarative templates describe the desired end state; deploying again gives the same result."},{lesson:"monitoring",prompt:"Users report a web app is slow. Azure status shows no problems. The team needs to find which dependency call is slow inside the app. Which tool?",options:["Application Insights","Azure Service Health","Azure Advisor","Azure Policy"],answer:0,explanation:"Application Insights traces requests and dependencies inside your app.",trap:"Service Health tells you about Azure platform issues, not your code's slow database call."},{lesson:"monitoring",prompt:"An admin wants to be notified automatically if Microsoft schedules maintenance that will affect VMs in their region. Which service should they configure alerts in?",options:["Azure Service Health","Application Insights","Azure Policy","Azure Pricing Calculator"],answer:0,explanation:"Service Health tracks planned maintenance, incidents, and advisories for your subscriptions and can alert you."},{lesson:"monitoring",prompt:"A VM shows as unavailable. You want to know whether that specific VM is affected by an Azure platform problem. Which view is MOST specific?",options:["Resource Health","Azure status page","Azure Advisor","Cost Management"],answer:0,explanation:"Resource Health shows the health of an individual resource. Azure status is global; Service Health is per subscription and region."}]),i=s("l5",[{lesson:"cloud-computing",kind:"yesno",prompt:"For each of the following statements, select Yes if the statement is true. Otherwise, select No.",options:["Cloud computing lets you provision resources in minutes instead of weeks.","With the consumption-based model, you must estimate and buy peak capacity up front.","Operational expenditure can be deducted in the same year it is spent."],answer:0,answers:[0,2],explanation:"Fast provisioning is a core cloud trait. Consumption-based means no peak buying up front. OpEx is typically deducted in the year spent, while CapEx depreciates over time."},{lesson:"cloud-computing",kind:"complete",prompt:"A company that pays a cloud provider monthly for the compute it used is incurring ____.",options:["operational expenditure","capital expenditure","depreciation","a fixed asset"],answer:0,explanation:"Pay-as-you-use services are OpEx."},{lesson:"cloud-computing",prompt:"A developer wants code to run whenever a new order is placed, scale automatically, and cost nothing when idle. Which approach should you recommend?",options:["Serverless computing","A dedicated host","A reserved virtual machine","A private cloud"],answer:0,explanation:"Event-driven, auto-scaling, no idle cost = serverless."},{lesson:"shared-responsibility",kind:"yesno",prompt:"For each of the following statements, select Yes if the statement is true. Otherwise, select No.",options:["For IaaS, the customer is responsible for installing application updates.","For SaaS, Microsoft is responsible for managing user devices.","For PaaS, Microsoft is responsible for the operating system."],answer:0,answers:[0,2],explanation:"IaaS app updates are the customer's. Devices are always the customer's. PaaS OS is Microsoft's."},{lesson:"shared-responsibility",prompt:"Your company moves file storage from an on-premises file server to Microsoft OneDrive (SaaS). Which responsibility does your company keep?",options:["Controlling who can access the files","Patching the storage servers","Physical security of the datacenter","Maintaining the OneDrive application code"],answer:0,explanation:"Access to your data is always your responsibility."},{lesson:"shared-responsibility",kind:"match",prompt:"Match each responsibility to who owns it in the shared responsibility model.",categories:["Always the customer","Always Microsoft","Varies by service type"],options:["Information and data","Physical network","Operating system","Devices (mobile and PCs)","Identity and directory infrastructure"],answer:0,answers:[0,1,2,0,2],explanation:"Data, devices, and accounts and identities are always yours. Physical hosts, network, and datacenter are always Microsoft's. The OS, network controls, applications, and identity and directory infrastructure shift with IaaS, PaaS, or SaaS.",trap:"Identity and directory INFRASTRUCTURE varies, but your accounts and identities are always your job."},{lesson:"cloud-models",prompt:"A hospital keeps patient records on servers in its own building, and uses Azure to run a patient-portal website that reads some of that data. Which cloud model is this?",options:["Hybrid cloud","Public cloud","Private cloud","Multi-cloud"],answer:0,explanation:"On-premises plus public cloud working together = hybrid."},{lesson:"cloud-models",kind:"complete",prompt:"A cloud model in which computing resources are used exclusively by one business or organization is a ____.",options:["private cloud","public cloud","hybrid cloud","community region"],answer:0,explanation:"Exclusive use by one organization = private cloud."},{lesson:"cloud-benefits",kind:"multi",prompt:"Which TWO are benefits of moving workloads from an on-premises datacenter to Azure? Each correct answer presents a complete solution.",options:["Resources can be scaled in and out with demand","You no longer need to buy and replace server hardware","You are no longer responsible for user identities","Every service has a 100% SLA"],answer:0,answers:[0,1],explanation:"Elastic scale and no hardware purchases are real benefits. Identities stay yours; no SLA is 100%."},{lesson:"cloud-benefits",prompt:"A company wants a reporting app to respond within two seconds even at month-end, using load tests and autoscaling. Which benefit is this?",options:["Performance predictability","Cost predictability","Governance","Sustainability"],answer:0,explanation:"Consistent performance under load = performance predictability."},{lesson:"cloud-benefits",kind:"match",prompt:"Match each scenario to the cloud benefit it demonstrates.",categories:["Scalability","Reliability","Predictability","Manageability"],options:["Adding VM instances automatically when traffic grows","Failing over to another region and continuing to run during an outage","Forecasting next month's spend with budgets and the Pricing Calculator","Deploying and configuring resources with templates and automation"],answer:0,answers:[0,1,2,3],explanation:"More instances under load = scalability. Recovering from failure and continuing to function = reliability. Knowing costs ahead = (cost) predictability. Templates and automation = management of the cloud."},{lesson:"cloud-service-types",kind:"yesno",prompt:"For each of the following statements, select Yes if the statement is true. Otherwise, select No.",options:["Azure Virtual Machines is an example of PaaS.","Azure App Service is an example of PaaS.","Microsoft Dynamics 365 is an example of SaaS."],answer:0,answers:[1,2],explanation:"VMs are IaaS. App Service is PaaS. Dynamics 365 is SaaS."},{lesson:"cloud-service-types",prompt:"A company wants to build a new web app quickly and does not want to manage servers, but must deploy its own custom code. Which service type should it use?",options:["PaaS","IaaS","SaaS","On-premises"],answer:0,explanation:"Custom code without servers to manage = PaaS."},{lesson:"regions-and-zones",kind:"yesno",prompt:"For each of the following statements, select Yes if the statement is true. Otherwise, select No.",options:["An availability zone is a separate Azure region.","Deploying VMs across availability zones can protect against a datacenter failure.","Region pairs help with disaster recovery."],answer:0,answers:[1,2],explanation:"Zones are inside a region. Spreading across zones survives a datacenter failure. Pairs support DR."},{lesson:"regions-and-zones",prompt:"A government agency in the United States requires an isolated instance of Azure with screened personnel. What should it use?",options:["Azure Government","A region pair","An availability set","A management group"],answer:0,explanation:"Azure Government is the US sovereign cloud."},{lesson:"resource-hierarchy",kind:"order",prompt:"Arrange the Azure organization levels from the broadest scope to the narrowest.",options:["Management groups","Subscriptions","Resource groups","Resources"],answer:0,explanation:"Management groups contain subscriptions, subscriptions contain resource groups, and resource groups contain resources. Policy and RBAC assigned higher up are inherited downward."},{lesson:"resource-hierarchy",kind:"yesno",prompt:"For each of the following statements, select Yes if the statement is true. Otherwise, select No.",options:["A resource group can contain resources from multiple Azure regions.","Deleting a resource group deletes all the resources it contains.","A resource group can belong to two subscriptions."],answer:0,answers:[0,1],explanation:"Resource groups can span regions and share a lifecycle, but belong to one subscription."},{lesson:"compute",prompt:"Your company must deploy 50 identical VMs that scale automatically based on CPU usage. Which Azure service should you use?",options:["Virtual Machine Scale Sets","Availability sets","Azure Virtual Desktop","Azure Container Instances"],answer:0,explanation:"Scale sets manage and autoscale identical VMs."},{lesson:"compute",kind:"multi",prompt:"Which TWO Azure services can host a containerized application? Each correct answer presents a complete solution.",options:["Azure Kubernetes Service","Azure Container Instances","Azure DNS","Azure Data Box"],answer:0,answers:[0,1],explanation:"AKS and ACI both run containers. DNS and Data Box do not host apps."},{lesson:"compute",prompt:"A company wants to add speech-to-text and translation to its app using prebuilt models, without hiring data scientists. Which service family should it use?",options:["Azure AI services","Azure Machine Learning","Azure IoT Edge","Azure Arc"],answer:0,explanation:"Prebuilt AI models behind APIs = Azure AI services."},{lesson:"networking",kind:"match",prompt:"Match each requirement to the Azure networking service that meets it.",categories:["VPN Gateway","ExpressRoute","VNet peering","Azure DNS"],options:["An encrypted connection from a branch office to Azure over the public internet","A private connection from your datacenter through a connectivity provider that does not use the public internet","Let resources in two Azure virtual networks talk privately over the Microsoft backbone","Host the name records for your company's domain on Azure infrastructure"],answer:0,answers:[0,1,2,3],explanation:"VPN Gateway sends encrypted traffic over the internet. ExpressRoute is a private link via a provider. Peering joins VNets. Azure DNS hosts DNS zones.",trap:"ExpressRoute is not encrypted by default — what it adds is privacy from the internet and predictable performance."},{lesson:"networking",prompt:"Your company needs a connection between its datacenter and Azure that offers higher reliability and lower latency than the internet, with traffic never crossing the public internet. What should you use?",options:["Azure ExpressRoute","A site-to-site VPN","VNet peering","Azure Bastion"],answer:0,explanation:"ExpressRoute = private, predictable connectivity."},{lesson:"networking",kind:"yesno",prompt:"For each of the following statements, select Yes if the statement is true. Otherwise, select No.",options:["A network security group can be associated with a subnet.","Azure DNS can host your public domain's DNS records.","A private endpoint exposes a service on a public IP address."],answer:0,answers:[0,1],explanation:"NSGs attach to subnets/NICs. Azure DNS hosts zones. A private endpoint uses a private IP."},{lesson:"storage",prompt:"You need to store backups that are accessed once a year. The data must be retained for 10 years at the lowest possible cost, and retrieval can take several hours. Which access tier should you use?",options:["Archive","Cold","Cool","Hot"],answer:0,explanation:"Lowest cost with hours of retrieval acceptable = Archive."},{lesson:"storage",kind:"match",prompt:"Match each description to the storage redundancy option.",categories:["LRS","ZRS","GRS","GZRS"],options:["Three copies in a single datacenter in the primary region only","Three copies across availability zones in the primary region only","Three copies in one datacenter in the primary region, plus copies in a secondary region","Copies across availability zones in the primary region, plus copies in a secondary region"],answer:0,answers:[0,1,2,3],explanation:"LRS = one datacenter. ZRS = three zones. GRS = LRS in the primary plus asynchronous copies in the paired secondary region. GZRS = ZRS in the primary plus a secondary region.",trap:"GRS protects against a regional disaster, but its primary-region copies sit in one datacenter. For zone failures you want ZRS or GZRS."},{lesson:"storage",prompt:"A company has 40 TB of data and a slow internet link. It wants to move the data to Azure as quickly as possible. What should it use?",options:["Azure Data Box","AzCopy","Azure File Sync","Azure Storage Explorer"],answer:0,explanation:"Offline transfer on a shipped device beats a slow network."},{lesson:"identity",kind:"yesno",prompt:"For each of the following statements, select Yes if the statement is true. Otherwise, select No.",options:["Conditional Access can require MFA based on the user's location.","Single sign-on requires users to enter a password for each app.","Microsoft Entra ID can provide identity for SaaS applications."],answer:0,answers:[0,2],explanation:"Conditional Access uses location. SSO avoids repeated passwords. Entra ID integrates with thousands of SaaS apps."},{lesson:"identity",prompt:"You need to let users from a partner organization access your company's app using their existing work accounts. What should you use?",options:["Microsoft Entra B2B collaboration","Azure RBAC alone","Microsoft Entra Domain Services","A ReadOnly lock"],answer:0,explanation:"B2B collaboration invites guests who sign in with their own identity."},{lesson:"security",kind:"complete",prompt:"The Zero Trust principle of ____ means limiting user access with just-in-time and just-enough access.",options:["least privilege","assume breach","verify explicitly","defense-in-depth"],answer:0,explanation:"Just-in-time / just-enough = least privilege."},{lesson:"security",prompt:"You need a service that provides security recommendations, a Secure Score, and threat protection for Azure and on-premises workloads. What should you use?",options:["Microsoft Defender for Cloud","Azure Policy","Microsoft Entra ID","Azure Service Health"],answer:0,explanation:"That is Defender for Cloud: posture management plus workload protection, hybrid included."},{lesson:"cost-management",kind:"yesno",prompt:"For each of the following statements, select Yes if the statement is true. Otherwise, select No.",options:["The cost of a VM can differ between Azure regions.","Outbound data transfer from Azure can incur charges.","Adding tags to resources increases their cost."],answer:0,answers:[0,1],explanation:"Region and egress affect cost. Tags are free metadata."},{lesson:"cost-management",kind:"match",prompt:"Match each tool to when you would use it.",categories:["Before migrating or deploying","After resources are running"],options:["Azure Pricing Calculator","Azure Migrate business case","Microsoft Cost Management","Azure Advisor cost recommendations"],answer:0,answers:[0,0,1,1],explanation:"The Pricing Calculator estimates planned resources and the Azure Migrate business case compares on-premises cost with Azure before you move. Cost Management analyzes actual spend and Advisor right-sizes what is already running.",trap:"The old TCO calculator has been retired — the Azure Migrate business case now does the on-premises vs. Azure comparison."},{lesson:"cost-management",kind:"complete",prompt:"To receive an email when a subscription's spending reaches 90% of a set amount, create a ____ in Microsoft Cost Management.",options:["budget","resource lock","policy initiative","management group"],answer:0,explanation:"Budgets trigger alerts at thresholds."},{lesson:"cost-management",prompt:"A company runs the same VM sizes in the same region continuously. Which option will provide the greatest discount?",options:["Azure Reservations","Spot VMs for production","Pay-as-you-go","Azure Hybrid Benefit for Linux"],answer:0,explanation:"Reservations reward steady, predictable usage with the biggest committed discount.",trap:"Spot is cheaper per hour but can be evicted — wrong for always-on production."},{lesson:"governance",kind:"yesno",prompt:"For each of the following statements, select Yes if the statement is true. Otherwise, select No.",options:["Azure Policy can prevent the creation of resources in unapproved regions.","A ReadOnly lock lets authorized users modify a resource.","Resource locks are inherited by child resources."],answer:0,answers:[0,2],explanation:"Policy can deny regions. ReadOnly blocks changes for everyone. Locks inherit down."},{lesson:"governance",prompt:"Your compliance team needs to discover where sensitive data is stored across Azure and on-premises, and classify it. What should you use?",options:["Microsoft Purview","Azure Policy","Azure Advisor","Microsoft Defender for Cloud"],answer:0,explanation:"Purview discovers, classifies, and governs data across environments."},{lesson:"governance",prompt:"Where can you download Microsoft's independent audit reports for Azure, such as SOC and ISO reports?",options:["Service Trust Portal","Azure portal Cost Management","Azure Status page","Azure Marketplace"],answer:0,explanation:"The Service Trust Portal publishes audit reports and compliance documentation."},{lesson:"governance",kind:"match",prompt:"Match each requirement to the Azure feature that meets it.",categories:["Azure Policy","Resource lock","Azure RBAC","Tags"],options:["Allow only approved VM sizes to be created","Stop anyone, even an Owner, from accidentally deleting a production database","Give a contractor read-only access to one resource group","Group resources by cost center for billing reports"],answer:0,answers:[0,1,2,3],explanation:"Policy enforces rules on resource properties. A CanNotDelete lock blocks deletion for everyone. RBAC controls who can do what at a scope. Tags are metadata used to organize and report costs.",trap:"RBAC can't stop an Owner from deleting — a lock applies regardless of role."},{lesson:"manage-and-deploy",kind:"complete",prompt:"Azure ____ lets you manage on-premises Windows and Linux servers from the Azure portal as if they were Azure resources.",options:["Arc","Advisor","Monitor","Migrate"],answer:0,explanation:"Azure Arc projects external resources into Azure Resource Manager."},{lesson:"manage-and-deploy",kind:"yesno",prompt:"For each of the following statements, select Yes if the statement is true. Otherwise, select No.",options:["Azure Cloud Shell can be accessed from a web browser.","Azure CLI can only be used on Windows computers.","ARM templates use a declarative syntax."],answer:0,answers:[0,2],explanation:"Cloud Shell runs in the browser. Azure CLI is cross-platform. ARM templates are declarative JSON."},{lesson:"manage-and-deploy",prompt:"You need to deploy the same set of Azure resources to multiple environments in a consistent, repeatable way. What should you use?",options:["ARM templates or Bicep","The Azure portal","Azure Advisor","Azure Service Health"],answer:0,explanation:"Infrastructure as code gives consistent, repeatable deployments."},{lesson:"manage-and-deploy",kind:"order",prompt:"Put the steps of an Azure deployment request in the order they happen.",options:["You send a request from the portal, Azure CLI, Azure PowerShell, or a template","Azure Resource Manager receives the request","Resource Manager authenticates and authorizes it with Microsoft Entra ID and RBAC","Resource Manager passes the request to the resource provider, which creates the resource"],answer:0,explanation:"Every tool talks to Azure Resource Manager. ARM checks identity and permissions, then hands the work to the right resource provider. That shared layer is why results are consistent across tools."},{lesson:"monitoring",kind:"yesno",prompt:"For each of the following statements, select Yes if the statement is true. Otherwise, select No.",options:["Azure Advisor provides recommendations to reduce cost.","Azure Service Health notifies you about planned maintenance that affects your resources.","Application Insights monitors the health of Azure datacenters."],answer:0,answers:[0,1],explanation:"Advisor has a Cost category. Service Health covers planned maintenance. Application Insights monitors your apps, not datacenters."},{lesson:"monitoring",prompt:"You want to analyze logs collected from VMs and Azure services by writing queries. What should you use?",options:["Log Analytics","Azure Advisor","Azure Service Health","Azure Pricing Calculator"],answer:0,explanation:"Log Analytics stores and queries Azure Monitor logs with KQL."},{lesson:"monitoring",kind:"order",prompt:"You want an SMS when a VM's available memory drops below a threshold. Put the Azure Monitor alert flow in order.",options:["Azure Monitor collects the VM's memory metric","An alert rule evaluates the metric against its condition","The condition is met and the alert fires","The action group sends the SMS"],answer:0,explanation:"Data comes in as metrics or logs, an alert rule evaluates it, a fired alert triggers its action group, and the action group notifies people (SMS, email, push) or runs automation."}]);e.s(["LEVELS",0,[{id:"l1",number:1,name:"Recall",difficulty:"Easy",blurb:'Definitions and "which service is…" questions. Make sure the vocabulary is solid.',questions:t},{id:"l2",number:2,name:"Understand",difficulty:"Medium",blurb:"Comparisons: choose between two services that sound alike.",questions:a},{id:"l3",number:3,name:"Full coverage",difficulty:"Mixed",blurb:"Every lesson, every official unit, every question format. Run it all in order or drill the lessons you pick. Progress saves as you go.",questions:n,fullCoverage:!0},{id:"l4",number:4,name:"Apply",difficulty:"Hard",blurb:"Scenarios with traps and close distractors — the questions that separate 650 from 800.",questions:r},{id:"l5",number:5,name:"Realistic mock",difficulty:"Exam",blurb:"45 questions in the official domain split, real exam formats, 45 minutes on the clock. No hints until you finish.",questions:i,timeLimit:45,examMode:!0}]],74068)}]);